<?php
/**
 * Plugin Name:       LLMs.txt URL Exclusions for SEOPress PRO
 * Description:       Remove specific URLs (posts, pages or any custom post type) from the llms.txt file generated by SEOPress PRO. Does not affect search engine indexing, robots meta or XML sitemaps.
 * Version:           1.0.0
 * Requires at least: 5.8
 * Requires PHP:      7.4
 * License:           GPL-2.0-or-later
 * License URI:       https://www.gnu.org/licenses/gpl-2.0.html
 * Text Domain:       llms-txt-url-exclusions-for-seopress-pro
 *
 * @package LLMS_URL_Exclusions
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

define( 'LUE_VERSION', '1.0.0' );
define( 'LUE_FILE', __FILE__ );
define( 'LUE_DIR', plugin_dir_path( __FILE__ ) );
define( 'LUE_URL', plugin_dir_url( __FILE__ ) );
define( 'LUE_BASENAME', plugin_basename( __FILE__ ) );

require_once LUE_DIR . 'includes/class-lue-plugin.php';

if ( is_admin() ) {
	require_once LUE_DIR . 'includes/class-lue-admin.php';
}

LUE_Plugin::init();

if ( is_admin() ) {
	LUE_Admin::init();
}
